        out.push(blank_code_spans(line));
    }
    out
}

/// Collect `(slug, line)` for every heading, in document order.
fn headings(lines: &[String]) -> Vec<(String, usize)> {
    let mut out = Vec::new();
    for (i, line) in lines.iter().enumerate() {
        let Some(rest) = line.strip_prefix('#') else {
            continue;
